{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "FK788, a phenoxyacetic acid-containing fused-ring compound, showed 55% oral bioavailability in healthy volunteers, supporting high F for the query's similar phenoxyacetic acid motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Cicaprost, a prostacyclin analogue with a cyclopentane diol core and acetic acid side chain, was completely bioavailable after oral dosing in healthy volunteers, supporting high F for the query's structurally related prostaglandin-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Iloprost, another prostacyclin analogue with a similar cyclopentane core and carboxylic acid side chain, had absolute oral bioavailability of 56-63% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Pravastatin, a carboxylic acid-containing drug with extensive hepatic first-pass extraction, had only 18% absolute bioavailability; however, its different scaffold and metabolism limit transferability, providing a weaker contradictory anchor.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Propafenone had low absolute bioavailability (16%) due to presystemic metabolism, but its basic amine/ketone structure is dissimilar to the acidic query, so it is a weak contradictory anchor.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a prostaglandin-like phenoxyacetic acid; the closest relevant analogues (FK788, cicaprost, iloprost) show oral bioavailability well above 20%, while low-F analogues are structurally and metabolically dissimilar. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "Morgan similarities to evidence molecules are low, limiting quantitative transferability.",
    "Unknown whether the query undergoes extensive first-pass metabolism or transporter-mediated clearance in humans."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

